   جایگزینی فیزیک سنگین سه‌بعدی با شبکه هش مکانی (Spatial Grid)

در اوج موج‌های بازی، بیش از ۲۵۰ دشمن همزمان به سمت بازیکن حرکت می‌کنند و تیغه‌های چرخان و پرتابه‌های انفجاری از میان آن‌ها عبور می‌کنند. استفاده از  CharacterBody3D  و تابع  move and slide()  برای تک‌تک دشمنان باعث می‌شود موتور فیزیک در هر فریم هزاران برخورد کپسولی سه‌بعدی را حل کند.

از آنجا که منطق گیم‌پلی روی صفحه افقی $XZ$ جریان دارد، جداسازی دشمنان و تشخیص اصابت پرتابه‌ها را به یک شبکه مکانی یکنواخت با بررسی مجذور فاصله منتقل کردم:

   gdscript
class name SpatialGrid
extends RefCounted

var cell size: float = 4.0
var buckets: Dictionary = {}

func clear() -  void:
    buckets.clear()

func  key(pos: Vector3) -  int:
    var cx := int(floor(pos.x / cell size))
    var cz := int(floor(pos.z / cell size))
    return (cx << 16) ^ (cz & 0xFFFF)

func insert(enemy id: int, pos: Vector3) -  void:
    var k :=  key(pos)
    if not buckets.has(k):
        buckets[k] = PackedInt32Array()
    buckets[k].append(enemy id)

func query radius(origin: Vector3, radius: float, positions: PackedVector3Array) -  PackedInt32Array:
    var hits := PackedInt32Array()
    var r sq := radius   radius
    var base x := int(floor(origin.x / cell size))
    var base z := int(floor(origin.z / cell size))

    for dx in range(-1, 2):
        for dz in range(-1, 2):
            var k := ((base x + dx) << 16) ^ ((base z + dz) & 0xFFFF)
            if not buckets.has(k):
                continue
            for id in buckets[k]:
                if origin.distance squared to(positions[id]) <= r sq:
                    hits.append(id)
    return hits


